    ['people', 'celine-uwinema', ['full_name' => 'Celine Uwinema', 'slug' => 'celine-uwinema', 'role' => 'phd-student', 'title' => 'PhD student — Geophysics', 'affiliation' => 'EAIFR', 'area_slug' => 'geophysics', 'photo' => '/uploads/people/celine-uwinema.jpg', 'bio' => "Supervisors: Dr. Catherine A. Meriaux, Dr. Antonio Costa, Dr. Silvia Massaro\n\nHer research falls in the domains of physical volcanology, particularly the dynamics of volcanic plumes from Nyiragongo and Nyamuragira in the East African Rift, using numerical models such as FALL3D, DISGAS, and TWODEE to simulate their dispersion and transport.\n\nExpected year of completion: 2028"]],
    ['people', 'sylvain-barayagwiza', ['full_name' => 'Sylvain Barayagwiza', 'slug' => 'sylvain-barayagwiza', 'role' => 'phd-student', 'title' => 'PhD student — Geophysics', 'affiliation' => 'EAIFR', 'area_slug' => 'geophysics', 'photo' => '/uploads/people/sylvain-barayagwiza.png', 'bio' => "Supervisors: Dr. Catherine A. Meriaux, Dr. Virginie Pinel, Prof. Alberto Armigliato\n\nHis PhD research focuses on major natural hazards in Western Rwanda, with emphasis on magma propagation associated with Nyiragongo volcano and landslides in a tectonically active region of the East African Rift.\n\nExpected year of completion: 2028"]],
