    ['people', 'sunday-joseph-ogenyi', ['full_name' => 'Sunday Joseph Ogenyi', 'slug' => 'sunday-joseph-ogenyi', 'role' => 'phd-student', 'title' => 'PhD student — Condensed Matter Physics', 'affiliation' => 'EAIFR', 'area_slug' => 'condensed-matter-physics', 'photo' => '/uploads/people/sunday-joseph-ogenyi.jpg', 'bio' => "Supervisors: Dr. Omololu Akin-Ojo, Dr. Nicola Seriani\n\nHis research interest is in the area of computational catalysis for renewable energy materials.\n\nExpected year of completion: 2026/2027"]],
